-- Name: Bus Images Overall Funnel - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH rid AS ( SELECT -- CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, route_id_train_no route_id FROM "user_interaction"."ui_ux_events" WHERE __time >= TIMESTAMP '2026-05-26 18:30:00' AND __time < TIMESTAMP '2026-06-17 18:30:00' AND app_code > 859110 -- AND event_group = 'NewBusImageLoaded' AND event_name IN ('NewBusImageLoaded') GROUP BY 1 -- , 2 ), SL AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(sl.__time, 'Asia/Kolkata')) AS DATE) AS doi, sl.mri_session_id, sl.route_id, sl.os, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sl.__time)), DATE(sl.doj)) = 0 THEN '0. Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sl.__time)), DATE(sl.doj)) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sl.__time)), DATE(sl.doj)) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sl.__time)), DATE(sl.doj)) > 2 THEN '3. DBD 2+' END AS dbd FROM user_interaction.seat_layout_details sl -- JOIN rid r ON r.route_id = CAST(sl.route_id AS VARCHAR) WHERE __time >= TIMESTAMP '2026-05-10 18:30:00' AND __time < TIMESTAMP '2026-06-18 18:30:00' AND sl.channel = 'MOBILE_APP' -- AND sl.os = 'iOS' AND sl.country = 'IND' -- AND app_code >= 859800 AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, sl.__time)), DATE(sl.doj)) <= 2 AND sl.status = 200 AND sl.tp_channel = 'INVALID' GROUP BY 1, 2, 3, 4, 5 ), mpax_deduped AS ( SELECT mri_session_id, route_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-10 18:30:00' AND __time < TIMESTAMP '2026-06-18 18:30:00' AND country = 'IND' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-10 18:30:00' AND __time < TIMESTAMP '2026-06-18 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-10 18:30:00' AND __time < TIMESTAMP '2026-06-18 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) SELECT b.doi, b.os, -- '11 to 17 May' AS time_period, COUNT(DISTINCT b.mri_session_id) SL, COUNT(DISTINCT mp.mri_session_id) CI, COUNT(DISTINCT oi.mri_session_id) Pay, COUNT(DISTINCT c.mri_session_id) Confirm FROM SL b LEFT JOIN mpax_deduped mp ON mp.mri_session_id = b.mri_session_id AND mp.route_id = b.route_id LEFT JOIN orderinfo_deduped oi ON oi.mri_session_id = b.mri_session_id AND oi.route_id = b.route_id LEFT JOIN confirm_deduped c ON c.mri_session_id = b.mri_session_id AND c.route_id = b.route_id GROUP BY 1, 2
